"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8033],{18033:d=>{d.exports=JSON.parse('{"schemaVersion":1,"locale":"ru","slug":"07-moshenniki","title":"Урок 07. Мошенники: Как не отдать всё за один звонок","sourceFingerprint":"66c16b9b445d9166699e0fb0e23e2c00fcf2477cb426df4fcb99130ef927358e","blocks":[{"id":"b001","markdown":"## Мошенники"},{"id":"b002","markdown":"Как не отдать всё за один звонок"},{"id":"b003","markdown":"К этому уроку у тебя уже есть план по долгам и первые деньги в подушке. И теперь главная угроза этим деньгам вовсе не инфляция и не падение рынка, а звонок с незнакомого номера."},{"id":"b004","markdown":"Цифры Банка России такие. За 2025 год с банковских счетов украли 29,3 млрд ₽, на 6,4% больше, чем годом раньше. Число операций без согласия клиентов при этом выросло на 31%. Во II квартале 2026 года потери клиентов составили почти 7,4 млрд ₽. Банки вернули из них только около 7%, это 514,6 млн ₽."},{"id":"b005","markdown":"При этом статистика ЦБ учитывает в основном операции без согласия клиента. Когда человек сам переводит деньги, потому что его убедили, вернуть их почти невозможно, а такие случаи в эти цифры обычно не попадают. Сбер, который считает шире, оценивал ущерб от мошенников за 2025 год в 275–295 млрд ₽."},{"id":"b006","markdown":"Вывод неприятный, но полезный: если перевод сделал ты сам, банк, скорее всего, ничего не вернёт. Защита держится на тебе."},{"id":"b007","markdown":"### Как устроена почти любая схема"},{"id":"b008","markdown":"Сценарии меняются каждый месяц, но скелет у них один и тот же, и его стоит выучить, а не запоминать отдельные истории."},{"id":"b009","markdown":"- Авторитет. Звонит \xabслужба безопасности банка\xbb, \xabследователь\xbb, \xabсотрудник ЦБ\xbb, \xab Госуслуги \xbb, курьер, начальник или родственник."},{"id":"b010","markdown":"- Срочность. Действовать нужно прямо сейчас: деньги уже выводят, на тебя оформляют кредит, посылка уедет обратно, родственник в беде."},{"id":"b011","markdown":"- Секретность. Никому не говори, это тайна следствия, банк в сговоре."},{"id":"b012","markdown":"- Действие. Назвать код из SMS, установить приложение, перевести деньги на \xabбезопасный счёт\xbb, снять наличные и отдать курьеру. Или взять кредит, чтобы \xabперехватить\xbb мошеннический."},{"id":"b013","markdown":"Если в разговоре сошлись хотя бы 2 пункта из 4, это почти наверняка мошенник, как бы правдоподобно всё ни звучало. Задача у них одна: не дать тебе остановиться и подумать."},{"id":"b014","markdown":"СКЕЛЕТ ПОЧТИ ЛЮБОЙ СХЕМЫ АВТОРИТЕТ \xabБАНК\xbb \xabСЛЕДОВАТЕЛЬ\xbb СРОЧНОСТЬ \xabПРЯМО СЕЙЧАС\xbb СЕКРЕТ- НОСТЬ \xabНИКОМУ НЕ ГОВОРИ\xbb ДЕЙСТВИЕ КОД ПЕРЕВОД 2 ИЗ 4: ПОЧТИ НАВЕРНЯКА МОШЕННИК ПОЛОЖИ ТРУБКУ И ПЕРЕЗВОНИ САМ"},{"id":"b015","markdown":"### Самые частые сценарии 2026 года"},{"id":"b016","markdown":"Многоэтапная атака. Сначала звонит \xabбанк\xbb и сообщает о подозрительной операции, потом подключается \xabполиция\xbb или \xabФСБ\xbb, и разговор может тянуться часами и днями. Финал всегда одинаковый: деньги нужно спасти, переведя их на \xabбезопасный счёт\xbb, или взять кредит, чтобы \xabзакрыть\xbb мошеннический. По оценке экспертов Финансового университета, это сейчас самая распространённая схема."},{"id":"b017","markdown":"Курьер и код. \xabВам доставка цветов или письма, назовите код из SMS\xbb. Код оказывается входом в Госуслуги или банковское приложение. Через Госуслуги потом оформляют кредиты и меняют данные. Поддельные квитанции. QR-код на квитанции ЖКХ или в рассылке \xabот управляющей компании\xbb ведёт на чужой счёт или фишинговый сайт."},{"id":"b018","markdown":"Сайты-клоны. Туры, билеты, товары заметно дешевле рынка на сайте, который выглядит как настоящий. После оплаты нет ни поездки, ни денег. Начальник или родственник. Сообщение в мессенджере с фото и именем знакомого человека: \xabтебе позвонят из органов, сделай, что скажут\xbb или \xabсрочно нужны деньги, потом объясню\xbb. Голос и видео сейчас тоже подделывают."},{"id":"b019","markdown":"\xabПодработка\xbb с переводами. Предлагают принять деньги на карту и перевести дальше за процент, либо продать или \xabсдать в аренду\xbb карту. Это называется дропперством, и о нём ниже отдельно."},{"id":"b020","markdown":"### 6 правил, которые закрывают почти всё"},{"id":"b021","markdown":"Безопасного счёта не существует. Ни банк, ни ЦБ, ни полиция никогда не просят перевести деньги, чтобы их \xabсохранить\xbb. Услышал эти слова, клади трубку. Коды из SMS и пуши никому не называй. Ни курьеру, ни \xabоператору\xbb, ни \xabсотруднику Госуслуг \xbb. Код это подпись, и тот, кто его получил, действует от твоего имени."},{"id":"b022","markdown":"Перезванивай сам. Положи трубку и набери номер банка, который напечатан на карте или указан в приложении. Не по номеру, который тебе продиктовали, и не \xabобратным звонком\xbb."},{"id":"b023","markdown":"Банки и госорганы не пишут в иностранных мессенджерах. С 2025 года их сотрудникам по закону запрещено общаться с клиентами через иностранные мессенджеры. Если \xabбанк\xbb или \xabследователь\xbb пишет в Telegram или WhatsApp, это не банк и не следователь."},{"id":"b024","markdown":"Ничего не устанавливай по просьбе. Ни \xabприложение для защиты\xbb, ни \xabобновление банка\xbb, ни программу для удалённого доступа. Через такие приложения мошенники получают доступ к телефону и банку, в том числе к бесконтактной оплате. Остановись. Почти все схемы держатся на спешке, а настоящие проблемы с банком подождут 10 минут, пока ты перезвонишь сам и посоветуешься с близкими."},{"id":"b025","markdown":"Мошенник или нет? Семь ситуаций"},{"id":"b026","markdown":"Звонит \xabслужба безопасности банка\xbb: с твоей карты пытаются вывести деньги, срочно переведи всё на безопасный счёт."},{"id":"b027","markdown":"Всё в порядке Мошенник"},{"id":"b028","markdown":"### Что настроить заранее"},{"id":"b029","markdown":"Многое можно сделать один раз и забыть. Самозапрет на кредиты. Про него было в уроке 4. Если кредит брать не планируешь, ставь полный. Самозапрет на SIM-карты. Через Госуслуги или МФЦ можно запретить оформлять на тебя договоры мобильной связи без личного присутствия. Ставится онлайн, а снимается только лично в МФЦ, так что мошенник снять его не сможет."},{"id":"b030","markdown":"Отказ от массовых звонков и рассылок. По закону можно отказаться от рекламных звонков и рассылок, оформляется у оператора связи. Меньше звонков от незнакомых номеров, проще заметить подозрительный. Второй ключ на Госуслугах. Включи вход с подтверждением и проверь в настройках, какие устройства и приложения имеют доступ к учётной записи."},{"id":"b031","markdown":"Подушка отдельно от повседневных денег. Держи подушку в банке, к которому не привязана карта для покупок, и не выводи её на главный экран. Если украдут доступ к одной карте, подушка не пострадает."},{"id":"b032","markdown":"\xabВторая рука\xbb для родителей. С 1 сентября 2025 года можно назначить в банке доверенное лицо, которое подтверждает переводы. Ты выбираешь, какие операции требуют подтверждения, и пока доверенное лицо не одобрит перевод, деньги не уйдут. Если оно не ответит за 12 часов, платёж отклоняется. Доступа к счёту у него при этом нет. Особенно полезно подключить такую услугу пожилым родственникам, а условия подключения у каждого банка свои."},{"id":"b033","markdown":"### Дропперство: как сесть в тюрьму за \xabподработку\xbb"},{"id":"b034","markdown":"Деньги, украденные у людей, мошенники гонят через цепочки чужих карт, чтобы их было сложнее отследить. Владельцев этих карт называют дропперами. Их ищут среди студентов и подростков, в чатах подработок и на сайтах вакансий: \xabпринимаешь переводы, оставляешь себе 5%\xbb."},{"id":"b035","markdown":"С 2025 года за это есть уголовная ответственность по статье 187 УК РФ. За передачу своей карты или доступа к ней мошенникам и за переводы по их указанию грозит до 3 лет лишения свободы. За использование чужих карт или покупку карт для таких операций до 6 лет и штраф до 1 млн ₽. Кроме того, ЦБ ведёт базу дропперов, и попавшим в неё банки ограничивают переводы и онлайн-банкинг."},{"id":"b036","markdown":"Своя карта, свой аккаунт в банке и свои SIM-карты никому не передаются ни за какие деньги. Расскажи об этом детям и младшим родственникам, они в группе риска."},{"id":"b037","markdown":"### Если это уже случилось"},{"id":"b038","markdown":"Действовать нужно в первые часы."},{"id":"b039","markdown":"- Позвони в банк по номеру с карты или из приложения и заблокируй карту и доступ в приложение. Если списание прошло без твоего согласия, у тебя есть время до конца следующего дня после уведомления об операции, чтобы сообщить о ней банку. Тогда банк по закону обязан разобраться и в большинстве случаев вернуть деньги."},{"id":"b040","markdown":"- Если перевёл сам, всё равно сразу звони в банк: иногда перевод удаётся остановить. Если банк провёл перевод на счёт, который уже был в базе мошенников ЦБ, деньги по закону должен вернуть сам банк."},{"id":"b041","markdown":"- Подай заявление в полицию. Лично или через Госуслуги. Без него банк и суд почти ничего сделать не смогут."},{"id":"b042","markdown":"- Проверь кредитную историю и Госуслуги: не оформили ли на тебя кредиты, не поменяли ли данные. Поставь самозапреты, если их ещё не было."},{"id":"b043","markdown":"- Предупреди близких, если взломали мессенджер: с него начнут писать им."},{"id":"b044","markdown":"Стыдиться тут нечего. Сценарии пишут профессионалы, обманывают и юристов, и банкиров, и айтишников. Чем быстрее начнёшь действовать, тем больше шансов что-то вернуть."},{"id":"b045","markdown":"### Самое главное"},{"id":"b046","markdown":"- Если перевёл сам, банк почти ничего не вернёт. Защита держится на тебе."},{"id":"b047","markdown":"- Схема почти всегда одна: авторитет, срочность, секретность и действие с деньгами или кодом."},{"id":"b048","markdown":"- Безопасного счёта не существует, коды никому не называй, перезванивай сам по номеру с карты."},{"id":"b049","markdown":"- Заранее поставь самозапреты на кредиты и SIM-карты, держи подушку отдельно, а родителям подключи \xabвторую руку\xbb."},{"id":"b050","markdown":"- Передавать свою карту за деньги это уголовная статья."},{"id":"b051","markdown":"Долги под контролем, подушка собрана и защищена. В следующем уроке разберёмся, как сделать, чтобы деньги работали."}],"terms":[{"id":"inflyatsiya","term":"Инфляция","definition":"рост общего уровня цен. На деле: денег стало больше, товаров столько же — каждый стоит дороже. Ты не стал богаче, просто ценники выросли"},{"id":"kreditnaya-istoriya","term":"Кредитная история","definition":"запись о том, как ты платил по кредитам. Плохая история или её отсутствие = отказ или ставка выше рыночной. Пустая история хуже, чем история с погашенными кредитами"}],"quizzes":[{"id":"07-moshenniki-q1","q":"Звонит \xabсотрудник службы безопасности банка\xbb и просит срочно перевести деньги на \xabбезопасный счёт\xbb, потому что их пытаются украсть. Что делать?","options":["Перевести, пока не поздно","Положить трубку и самому позвонить в банк по номеру с карты","Перевести половину, чтобы проверить"],"correct":1},{"id":"07-moshenniki-q2","q":"Курьер просит назвать код из SMS, чтобы подтвердить доставку цветов. Что это скорее всего?","options":["Попытка получить доступ к твоим Госуслугам или банку","Обычная процедура службы доставки","Проверка номера телефона оператором связи"],"correct":0},{"id":"07-moshenniki-q3","q":"В чате подработок предлагают 5% за то, чтобы принимать переводы на свою карту и пересылать их дальше. Чем это грозит?","options":["Ничем, это обычная подработка","Только блокировкой карты на один день","Уголовной ответственностью по статье 187 УК РФ и попаданием в базу дропперов ЦБ"],"correct":2}],"officialSources":[]}')}}]);